import{_ as p,a0 as l,w as o,s as r,I as n,x as t,a1 as i,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"awk 系列：如何使用 awk 輸出文本中的字段和列 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 輸出文本中的字段和列 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 輸出文本中的字段和列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 輸出文本中的字段和列 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 2 - How to Use Awk to Print Fields and Columns in File","title":"awk 系列：如何使用 awk 輸出文本中的字段和列","tag":"awk","desc":""},"relativePath":"awk/Part 2 - How to Use Awk to Print Fields and Columns in File.md","filePath":"[post].md"}'),k={name:"awk/Part 2 - How to Use Awk to Print Fields and Columns in File.md"};function h(g,s,u,w,m,c){const a=l("Link");return o(),r("div",null,[s[18]||(s[18]=n("h1",{id:"awk-系列-如何使用-awk-輸出文本中的字段和列",tabindex:"-1"},[t("awk 系列：如何使用 awk 輸出文本中的字段和列 "),n("a",{class:"header-anchor",href:"#awk-系列-如何使用-awk-輸出文本中的字段和列","aria-label":"Permalink to “awk 系列：如何使用 awk 輸出文本中的字段和列”"},"​")],-1)),s[19]||(s[19]=n("p",null,"在 Awk 系列的這一節中，我們將看到 awk 最重要的特性之一，字段編輯。",-1)),s[20]||(s[20]=n("p",null,"首先我們要知道，Awk 能夠自動將輸入的行，分隔為若干字段。每一個字段就是一組字符，它們和其他的字段由一個內部字段分隔符分隔開來。",-1)),s[21]||(s[21]=n("p",null,[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2016/04/Awk-Print-Fields-and-Columns.png",alt:""})],-1)),s[22]||(s[22]=n("p",null,[n("em",null,"Awk 輸出字段和列")],-1)),n("p",null,[s[1]||(s[1]=t("如果你熟悉 Unix/Linux 或者懂得 ",-1)),i(a,{href:"http://www.tecmint.com/category/bash-shell/"},{default:e(()=>[...s[0]||(s[0]=[t("bash shell 編程",-1)])]),_:1}),s[2]||(s[2]=t("，那麼你應該知道什麼是內部字段分隔符（IFS）變量。awk 中默認的 IFS 是製表符和空格。",-1))]),s[23]||(s[23]=d(`<p>awk 中的字段分隔符的工作原理如下：當讀到一行輸入時，將它按照指定的 IFS 分割為不同字段，第一組字符就是字段一，可以通過 $1 來訪問，第二組字符就是字段二，可以通過 $2 來訪問，第三組字符就是字段三，可以通過 $3 來訪問，以此類推，直到最後一組字符。</p><p>為了更好地理解 awk 的字段編輯，讓我們看一個下面的例子：</p><p><strong>例 1</strong>：我創建了一個名為 tecmintinfo.txt 的文本文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi tecmintinfo.txt</span></span>
<span class="line"><span># cat tecmintinfo.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Create-File-in-Linux.png" alt=""></p><p><em>在 Linux 上創建一個文件</em></p><p>然後在命令列中，我試着使用下面的命令從文本 tecmintinfo.txt 中輸出第一個，第二個，以及第三個字段。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{print $1 $2 $3 }&#39; tecmintinfo.txt</span></span>
<span class="line"><span>TecMint.comisthe</span></span></code></pre></div><p>從上面的輸出中你可以看到，前三個字段的字符是以空格為分隔符輸出的：</p><ul><li>字段一是 “TecMint.com”，可以通過 <code>$1</code> 來訪問。</li><li>字段二是 “is”，可以通過 <code>$2</code> 來訪問。</li><li>字段三是 “the”，可以通過 <code>$3</code> 來訪問。</li></ul><p>如果你注意觀察輸出的話可以發現，輸出的字段值並沒有被分隔開，這是 print 函數默認的行為。</p><p>為了使輸出看得更清楚，輸出的字段值之間使用空格分開，你需要添加 (,) 操作符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{print $1, $2, $3; }&#39; tecmintinfo.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TecMint.com is the</span></span></code></pre></div><p>需要記住而且非常重要的是，<code>($)</code> 在 awk 和在 shell 腳本中的使用是截然不同的！</p><p>在 shell 腳本中，<code>($)</code> 被用來獲取變量的值。而在 awk 中，<code>($)</code> 只有在獲取字段的值時才會用到，不能用於獲取變量的值。</p><p><strong>例 2</strong>：讓我們再看一個例子，用到了一個名為 my_shoping.list 的包含多行的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>No	  Item_Name		            Unit_Price	Quantity	Price</span></span>
<span class="line"><span>1	    Mouse			              #20,000		   1		    #20,000</span></span>
<span class="line"><span>2 	    Monitor			            #500,000	   1		    #500,000</span></span>
<span class="line"><span>3	    RAM_Chips		            #150,000	   2		    #300,000</span></span>
<span class="line"><span>4	    Ethernet_Cables	        #30,000		   4		    #120,000</span></span></code></pre></div><p>如果你只想輸出購物清單上每一個物品的<code>單價</code>，你只需運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{print $2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name Unit_Price</span></span>
<span class="line"><span>Mouse #20,000</span></span>
<span class="line"><span>Monitor #500,000</span></span>
<span class="line"><span>RAM_Chips #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><p>可以看到上面的輸出不夠清晰，awk 還有一個 <code>printf</code> 的命令，可以幫助你將輸出格式化。</p><p>使用 <code>printf</code> 來格式化 Item_Name 和 Unit_Price 的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{printf &quot;%-10s %s\\n&quot;,$2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name  Unit_Price</span></span>
<span class="line"><span>Mouse      #20,000</span></span>
<span class="line"><span>Monitor    #500,000</span></span>
<span class="line"><span>RAM_Chips  #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>使用 awk 過濾文本或字符串時，字段編輯的功能是非常重要的。它能夠幫助你從一個表的數據中得到特定的列。一定要記住的是，awk 中 <code>($)</code> 操作符的用法與其在 shell 腳本中的用法是不同的！</p><p>希望這篇文章對您有所幫助。如有任何疑問，可以在評論區域發表評論。</p><hr>`,26)),n("p",null,[s[4]||(s[4]=t("via: ",-1)),i(a,{href:"http://www.tecmint.com/awk-print-fields-columns-with-space-separator/"},{default:e(()=>[...s[3]||(s[3]=[t("http://www.tecmint.com/awk-print-fields-columns-with-space-separator/",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=t("作者：",-1)),i(a,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...s[5]||(s[5]=[t("Aaron Kili",-1)])]),_:1}),s[10]||(s[10]=t(" 譯者：",-1)),i(a,{href:"https://github.com/Cathon"},{default:e(()=>[...s[6]||(s[6]=[t("Cathon",-1)])]),_:1}),s[11]||(s[11]=t("，",-1)),i(a,{href:"https://github.com/ictlyh"},{default:e(()=>[...s[7]||(s[7]=[t("ictlyh",-1)])]),_:1}),s[12]||(s[12]=t(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[t("LCTT",-1)])]),_:1}),s[16]||(s[16]=t(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[t("Linux中國",-1)])]),_:1}),s[17]||(s[17]=t(" 榮譽推出",-1))])])}const x=p(k,[["render",h]]);export{C as __pageData,x as default};
